import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes, Link, useLocation, Navigate } from 'react-router-dom';
import Login from './component/Login';
import Signup from './component/Signup';
import HomePage from './component/HomePage';
import AdminLogin from './component/AdminLogin';
import AdminPage from './component/AdminPage';
import './App.css';

function App() {
  const [user, setUser] = useState(null);

  const handleLogin = (userData) => {
    setUser(userData);
    localStorage.setItem('userEmail', userData.email);
    localStorage.setItem('userRole', userData.role || 'user'); 
    localStorage.setItem('username', userData.username || '');
  };

  return (
    <Router>
      <AppContent user={user} onLogin={handleLogin} />
    </Router>
  );
}

function PrivateRoute({ user, children }) {
  return user ? children : <Navigate to="/" replace />;
}

function AdminRoute({ user, children }) {
  if (!user) return <Navigate to="/admin-login" replace />;
  if (user.role !== 'admin') return <Navigate to="/" replace />;
  return children;
}

function AppContent({ user, onLogin }) {
  const location = useLocation();
  const hideNav = location.pathname === '/home' || location.pathname === '/admin';

  return (
    <>
      <Routes>
        <Route path="/" element={<Login onLogin={onLogin} />} />
        <Route path="/signup" element={<Signup />} />
        <Route path="/home" element={<PrivateRoute user={user}><HomePage user={user} /></PrivateRoute>} />
        <Route path="/admin-login" element={<AdminLogin onLogin={onLogin} />} />
        <Route path="/admin" element={<AdminRoute user={user}><AdminPage /></AdminRoute>} />
      </Routes>

      {!hideNav && (
        <nav className="nav-bar">
          <Link to="/">Login</Link>
          <span className="separator">|</span>
          <Link to="/signup">Signup</Link>
          <span className="separator">|</span>
          <Link to="/admin-login">Admin Login</Link>
        </nav>
      )}
    </>
  );
}

export default App;
